    lines: list[tuple[int, str]], pos: int, base_indent: int,
) -> tuple[list[Any], int]:
    result: list[Any] = []
    i = pos
    while i < len(lines):
        ci, content = lines[i]
        if ci != base_indent:
            break
        m = re.match(r"''^-'"\\s+(.*)\", content)
        if not m:
            break
        rest = m.group(1)
        if rest == \"\" or rest is None:
            # nested block sequence item
            i += 1
            if i < len(lines) and lines[i][0] > base_indent:
                child = {}
                i = _parse_nested_mapping(lines, i, base_indent, child)
                result.append(child)
            else:
                result.append(None)
        else:
            rest_stripped = rest.strip()
            m2 = re.match(r\""'^([''^:]+?):'"\\s*(.*)\", rest_stripped)
            if m2:
                # inline mapping in sequence
                child = {m2.group(1).strip(): _coerce_scalar(m2.group(2).strip())}
                result.append(child)
                i += 1
            else:
                result.append(_coerce_scalar(rest_stripped))
                i += 1
    return result, i


def _parse_nested_mapping(
    lines: list[tuple[int, str]], pos: int, parent_indent: int, target: dict,
) -> int:
    \"\"\"Parse lines at deeper indent into target dict; return next pos.\"\"\"
    i = pos
    while i < len(lines):
        ci, content = lines[i]
        if ci <= parent_indent:
            break
        key, value, consumed = _parse_one_kv(lines, i, ci)
        target[key] = value
        i += consumed
    return i


def _parse_mapping(
    lines: list[tuple[int, str]], pos: int, base_indent: int,
) -> tuple[dict[str, Any], int]:
    result: dict[str, Any] = {}
    i = pos
    while i < len(lines):
