"""Retry utility: configurable max_retries via kwarg, default 2."""
import functools
from mini_harness.logger import log


def with_retry(stage: str, default_max_retries: int = 2):
    """Decorator: retry on failure, max_retries configurable via kwarg.

    The decorated function may accept max_retries=N to override the default.
    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            max_retries = kwargs.pop("max_retries", default_max_retries)
            last_exc = None
            for attempt in range(1, max_retries + 2):
                try:
                    result = func(*args, **kwargs)
                    log(attempt, stage, "ok", retries_used=attempt - 1)
                    return result
                except Exception as exc:
                    last_exc = exc
                    log(attempt, stage, "fail", error=str(exc))
            raise last_exc  # type: ignore[misc]
        return wrapper
    return decorator

"""clean stage: cleaning rules."""
import re
from typing import Any, List, Tuple

from mini_harness.retry import with_retry


def _to_snake_case(name: str) -> str:
    """Convert CamelCase / PascalCase / spaced field names to snake_case."""
    s = name.strip().replace(" ", "_").replace("-", "_")
    s = re.sub(r"([A-Z]+)([A-Z][a-z])", r"\1_\2", s)
    s = re.sub(r"([a-z\d])([A-Z])", r"\1_\2", s)
    return s.lower()


@with_retry(stage="clean")
def clean(
    records: List[dict[str, Any]], **kwargs: Any,
) -> Tuple[List[dict[str, Any]], List[dict[str, Any]]]:
    """Clean record list, return (cleaned, rejects)."""
    cleaned: List[dict[str, Any]] = []
    rejects: List[dict[str, Any]] = []

    for record in records:
        # drop empty rows
        if all(v is None or str(v).strip() == "" for v in record.values()):
            rejects.append({**record, "_reject_reason": "empty_row"})
            continue

        # field names to snake_case
        record = {_to_snake_case(k): v for k, v in record.items()}

        # missing id -> rejects
        if "id" not in record or record["id"] is None or str(record["id"]).strip() == "":
            rejects.append({**record, "_reject_reason": "missing_id"})
            continue

        cleaned.append(record)

    return cleaned, rejects

"""extract stage: read CSV / JSONL files, return record list."""
import csv
import json
from pathlib import Path
from typing import Any, List

from mini_harness.retry import with_retry


@with_retry(stage="extract")
def extract(source: Path, **kwargs: Any) -> List[dict[str, Any]]:
    """Extract all records from a CSV or JSONL file."""
    suffix = source.suffix.lower()
    if suffix == ".csv":
        return _read_csv(source)
    if suffix == ".jsonl":
        return _read_jsonl(source)
    raise ValueError(f"Unsupported file type: {suffix}")


def _read_csv(path: Path) -> List[dict[str, Any]]:
    with open(path, "r", encoding="utf-8-sig", newline="") as f:
        reader = csv.DictReader(f)
        return list(reader)


def _read_jsonl(path: Path) -> List[dict[str, Any]]:
    records: List[dict[str, Any]] = []
    with open(path, "r", encoding="utf-8-sig") as f:
        for line in f:
            line = line.strip()
            if line:
                records.append(json.loads(line))
    return records

